from pathlib import Path
base=Path(r'D:\repository\数据湖\data\cnequity')
def ds(p): return sum(f.stat().st_size for f in p.rglob('*') if f.is_file())
print('=== data/cnequity 各子树(当前) ===')
for sub in sorted(base.iterdir(), key=lambda x:-(ds(x) if x.is_dir() else x.stat().st_size)):
    if sub.is_dir(): print(f'  {ds(sub)/1e6:8.1f} MB  {sub.name}/')
    else: print(f'  {sub.stat().st_size/1e6:8.1f} MB  {sub.name}')
print('\n=== meta 各子树 ===')
meta=base/'meta'
for sub in sorted(meta.iterdir(), key=lambda x:-(ds(x) if x.is_dir() else x.stat().st_size)):
    if sub.is_dir(): print(f'  {ds(sub)/1e6:8.2f} MB  {sub.name}/')
    else: print(f'  {sub.stat().st_size/1e6:8.2f} MB  {sub.name}')
print('\n=== curated / derived 大项 ===')
for grp in ['curated','derived','staging']:
    g=base/grp
    if not g.exists(): continue
    print(f' [{grp}]')
    items=[]
    for sub in g.iterdir():
        if sub.is_dir(): items.append((ds(sub),sub.name))
        else: items.append((sub.stat().st_size,sub.name))
    for sz,nm in sorted(items,reverse=True)[:6]:
        print(f'    {sz/1e6:8.2f} MB  {nm}')
print('\n=== meta/state & checkpoints 明细 ===')
for grp in ['state','checkpoints','source_cache','raw']:
    g=meta/grp
    if not g.exists(): continue
    print(f' [{grp}] 合计 {ds(g)/1e6:.1f} MB')
    items=[]
    for sub in g.iterdir():
        if sub.is_dir(): items.append((ds(sub),sub.name+'/'))
        else: items.append((sub.stat().st_size,sub.name))
    for sz,nm in sorted(items,reverse=True)[:8]:
        print(f'    {sz/1e6:7.2f} MB  {nm}')

